#!/usr/bin/env python3

import subprocess
import sys
from user_config import get_usernames, get_passwords, get_sudo_config

def run_command(command):
    """Run a shell command and return the result"""
    try:
        result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        print(f"Error running command '{command}': {e}")
        print(f"stderr: {e.stderr}")
        return None

def main():
    # Get the data from our config functions
    usernames = get_usernames()
    passwords = get_passwords()
    sudo_config = get_sudo_config()

    print("Setting up users...")

    # Create each user and set their password
    for username in usernames:
        # Create the user
        print(f"Creating user: {username}")
        result = run_command(f"useradd -m {username}")
        if result is None:
            print(f"Failed to create user {username}")
            continue

        # Set the password
        if username in passwords:
            print(f"Setting password for user: {username}")
            password = passwords[username]
            try:
                # Using chpasswd to set the password
                process = subprocess.Popen(['chpasswd'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                stdout, stderr = process.communicate(input=f"{username}:{password}")
                if process.returncode != 0:
                    print(f"Failed to set password for {username}: {stderr}")
                else:
                    print(f"Password set for {username}")
            except Exception as e:
                print(f"Exception while setting password for {username}: {e}")

    # Add sudo configuration to /etc/sudoers
    print("Adding sudo configuration...")
    try:
        with open('/etc/sudoers', 'a') as sudoers_file:
            sudoers_file.write(f"\n{sudo_config}\n")
        print("Sudo configuration added successfully")
    except PermissionError:
        print("Permission denied: Unable to write to /etc/sudoers")
        print("Try running with sudo privileges")
    except Exception as e:
        print(f"Error writing to /etc/sudoers: {e}")

    print("User setup completed!")

if __name__ == "__main__":
    main()
